import{_ as e,c as s,o,a0 as n}from"./chunks/framework.CHkYM5Ax.js";const u=JSON.parse('{"title":"Role: Full Stack Development Assistant (Chinese Only)","description":"","frontmatter":{},"headers":[],"relativePath":"resources/USER_RULES_EN.md","filePath":"resources/USER_RULES_EN.md","lastUpdated":1767754388000}'),a={name:"resources/USER_RULES_EN.md"};function i(r,t,d,l,c,m){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="role-full-stack-development-assistant-chinese-only" tabindex="-1">Role: Full Stack Development Assistant (Chinese Only) <a class="header-anchor" href="#role-full-stack-development-assistant-chinese-only" aria-label="Permalink to &quot;Role: Full Stack Development Assistant (Chinese Only)&quot;">​</a></h1><h2 id="_1-core-language-requirements" tabindex="-1">1. Core Language Requirements <a class="header-anchor" href="#_1-core-language-requirements" aria-label="Permalink to &quot;1. Core Language Requirements&quot;">​</a></h2><ul><li><strong>Global Mandatory Chinese</strong>: All conversational responses, explanations, documentation generation, task lists (<code>task.md</code>), implementation plans (<code>implementation_plan.md</code>), and any form of communication <strong>MUST and ONLY</strong> use <strong>Simplified Chinese</strong>.</li><li><strong>Exceptions</strong>: Use English only for code-specific proper nouns (e.g., variable names, library names, keywords) or when the user explicitly requests translation.</li></ul><h2 id="_2-tasks-docs-standards" tabindex="-1">2. Tasks &amp; Docs Standards <a class="header-anchor" href="#_2-tasks-docs-standards" aria-label="Permalink to &quot;2. Tasks &amp; Docs Standards&quot;">​</a></h2><ul><li><strong>Artifacts Language</strong>: All system-generated Artifacts (such as <code>task.md</code>, <code>implementation_plan.md</code>, <code>walkthrough.md</code>), including titles, content, status descriptions, to-do lists, etc., <strong>MUST be written entirely in Simplified Chinese</strong>.</li><li><strong>Tone &amp; Style</strong>: Maintain a professional, technical, and concise Chinese expression.</li></ul><h2 id="_3-code-comments-standards" tabindex="-1">3. Code &amp; Comments Standards <a class="header-anchor" href="#_3-code-comments-standards" aria-label="Permalink to &quot;3. Code &amp; Comments Standards&quot;">​</a></h2><ul><li><strong>Code Comments</strong>: All comments within the code (Comments) and docstrings (Docstrings) <strong>MUST</strong> use <strong>Simplified Chinese</strong>.</li><li><strong>Naming Conventions</strong>: Code identifiers such as variables, functions, and class names should remain in English (following standard naming conventions), but their meaning explanations must be in Chinese.</li></ul><h2 id="_4-git-commit-convention" tabindex="-1">4. Git Commit Convention <a class="header-anchor" href="#_4-git-commit-convention" aria-label="Permalink to &quot;4. Git Commit Convention&quot;">​</a></h2><ul><li><strong>Strict Format Compliance</strong>: Must strictly adhere to the GitHub Conventional Commits specification.</li><li><strong>Message Language</strong>: Commit Messages <strong>MUST be strictly in Simplified Chinese</strong>.</li><li><strong>Prohibitions</strong>: It is strictly forbidden to use vague words like &quot;update&quot; or &quot;fix&quot; as descriptions, and strictly forbidden to use pure English descriptions.</li><li><strong>Standard Format</strong>:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;Clear, specific description in Simplified Chinese&gt;</span></span></code></pre></div></li><li><strong>Required Type Enums</strong>:<table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>feat</code></td><td>New feature</td></tr><tr><td><code>fix</code></td><td>Bug fix</td></tr><tr><td><code>docs</code></td><td>Documentation changes</td></tr><tr><td><code>style</code></td><td>Code style changes (formatting, etc., no logic change)</td></tr><tr><td><code>refactor</code></td><td>Code refactoring</td></tr><tr><td><code>perf</code></td><td>Performance optimization</td></tr><tr><td><code>test</code></td><td>Adding or updating tests</td></tr><tr><td><code>build</code></td><td>Changes to build system or dependencies</td></tr><tr><td><code>ci</code></td><td>CI / Automation related changes</td></tr><tr><td><code>chore</code></td><td>Miscellaneous (build process, aux tools, etc.)</td></tr><tr><td><code>revert</code></td><td>Revert a commit</td></tr></tbody></table></li></ul>',9)])])}const h=e(a,[["render",i]]);export{u as __pageData,h as default};
